import {
  RIVET_PAGE_DATA_ELEMENT_ID,
  type HostedRivetPage,
  type RivetPage,
  type RivetPageHead,
  type RivetPageShareCard,
} from '../types/rivet-page-types';
import { escapeScriptJson } from './scriptJson';

const PAGE_HEAD_MARKER = '<meta name="rivet-page-head" />';
const renderPageDataElement = (json: string): string =>
  `<script id="${RIVET_PAGE_DATA_ELEMENT_ID}" type="application/json">${json}</script>`;
const PAGE_DATA_PLACEHOLDER = renderPageDataElement('null');

const escapeHtml = (value: string): string =>
  value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const renderShareCardTags = (
  title: string,
  { description, imageUrl }: RivetPageShareCard,
): string[] =>
  [
    ['name', 'description', description],
    ['property', 'og:type', 'website'],
    ['property', 'og:title', title],
    ['property', 'og:description', description],
    ['property', 'og:image', imageUrl],
    ['name', 'twitter:card', 'summary_large_image'],
    ['name', 'twitter:title', title],
    ['name', 'twitter:description', description],
    ['name', 'twitter:image', imageUrl],
  ].map(
    ([attribute, key, content]) =>
      `<meta ${attribute}="${key}" content="${escapeHtml(content)}" />`,
  );

const renderHead = ({ title, shareCard, robots }: RivetPageHead): string =>
  [
    ...(robots ? [`<meta name="robots" content="${robots}" />`] : []),
    `<title>${escapeHtml(title)}</title>`,
    ...(shareCard ? renderShareCardTags(title, shareCard) : []),
  ].join('\n    ');

export const composeRivetPage = ({
  shell,
  page,
  head,
}: {
  shell: string;
  page: RivetPage | HostedRivetPage;
  head: RivetPageHead;
}): string => {
  if (
    !shell.includes(PAGE_HEAD_MARKER) ||
    !shell.includes(PAGE_DATA_PLACEHOLDER)
  ) {
    throw new Error('Rivet page shell is missing its head or data placeholder');
  }
  return shell
    .replace(PAGE_HEAD_MARKER, () => renderHead(head))
    .replace(PAGE_DATA_PLACEHOLDER, () =>
      renderPageDataElement(escapeScriptJson(page)),
    );
};
